		public byte* AppGroup;
	}

	/// <summary>
	/// ARKit-specific info for the platform-based Vuforia Fusion Provider
	/// The pointers contained in this data structure are owned by Vuforia Engine and should
	/// be used with caution by the developer. For example do not release the session, do not pause
	/// the session, do not reconfigure it, doing so will cause Vuforia Engine&apos;s handling of the information
